    private async Task<HttpResponseMessage> SendAsync(
        HttpMethod method,
        string requestUri,
        HttpContent? content,
        CancellationToken cancellationToken)
    {
        using var request = new HttpRequestMessage(method, requestUri) { Content = content };
        return await _http.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken);
    }

    private static HttpClient NewClient(string baseUrl, string key)
    {
        var http = new HttpClient { BaseAddress = ValidateCredentialedBaseAddress(baseUrl) };
        http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
        http.DefaultRequestHeaders.UserAgent.ParseAdd($"jt/{Program.Version}");
        return http;
    }

    private static Uri ValidateCredentialedBaseAddress(string baseUrl)
    {
        if (!Uri.TryCreate(baseUrl, UriKind.Absolute, out var uri))
        {
            throw new InvalidOperationException("JOBTRACK_API_URL must be an absolute URL.");
        }

        if (uri.Scheme == Uri.UriSchemeHttps)
        {
            return uri;
        }

        if (uri.Scheme == Uri.UriSchemeHttp && uri.IsLoopback)
        {
            return uri;
        }

        throw new InvalidOperationException(
            "JOBTRACK_API_URL must use HTTPS unless it is an explicit local loopback HTTP URL.");
    }

    private static async Task<string> ReadSuccessfulBodyAsync(
        string command,
        HttpResponseMessage response,
        CancellationToken cancellationToken)
    {
        var body = await ReadBodyWithLimitAsync(response.Content, MaxResponseBodyBytes, cancellationToken);
        if (!response.IsSuccessStatusCode)
        {
            throw new JobTrackApiException(
                command,
                response.StatusCode,
                response.ReasonPhrase,
                body.Text,
                body.Truncated,
                MaxResponseBodyBytes);
        }

        if (body.Truncated)
        {
            throw new InvalidOperationException($"{command}: response body exceeded {MaxResponseBodyBytes} bytes.");
        }

        return body.Text;
    }

    private static async Task<ResponseBody> ReadBodyWithLimitAsync(
        HttpContent? content,
        int maxBytes,
        CancellationToken cancellationToken)
    {
        if (content is null)
        {
            return new ResponseBody("", false);
        }

        await using var stream = await content.ReadAsStreamAsync(cancellationToken);
        using var body = new MemoryStream();
        var buffer = new byte[Math.Min(DefaultStreamCopyBufferSize, maxBytes + 1)];

        while (true)
        {
            var remaining = maxBytes - (int)body.Length;
            var readLength = Math.Min(buffer.Length, remaining + 1);
            var read = await stream.ReadAsync(buffer.AsMemory(0, readLength), cancellationToken);
            if (read == 0)
            {
                return new ResponseBody(DecodeBody(content, body.ToArray()), false);
            }

            if (body.Length + read > maxBytes)
            {
                var allowed = maxBytes - (int)body.Length;
                if (allowed > 0)
                {
                    body.Write(buffer, 0, allowed);
                }

                return new ResponseBody(DecodeBody(content, body.ToArray()), true);
            }

            body.Write(buffer, 0, read);
        }
    }

    private static string DecodeBody(HttpContent content, byte[] body)
    {
        var charset = content.Headers.ContentType?.CharSet?.Trim('"');
        if (!string.IsNullOrWhiteSpace(charset))
        {
            try
            {
                return Encoding.GetEncoding(charset).GetString(body);
            }
            catch (ArgumentException)
            {
                // Fall back to UTF-8 for malformed server charset metadata.
            }
        }

        return Encoding.UTF8.GetString(body);
    }

    private static string EscapePathSegment(string value)
    {
        return Uri.EscapeDataString(value);
    }
