[Description("List comments for a task.")]
internal sealed class TaskCommentsCommand(IJobTrackApi api, IJobTrackOutput output)
    : AsyncCommand<TaskCommentsSettings>
{
    protected override async Task<int> ExecuteAsync(
        CommandContext context,
        TaskCommentsSettings settings,
        CancellationToken cancellationToken)
    {
        var comments = await api.GetTaskCommentsAsync(settings.TaskId, cancellationToken);

        if (!settings.UnsafeShowUntrustedComments)
        {
            if (settings.Json)
            {
                await output.Out.WriteLineAsync(JsonText.ToJson(CommentOutput.Redacted(comments)));
                return 0;
            }

            for (var index = 0; index < comments.Count; index++)
            {
                await output.Out.WriteLineAsync(CommentOutput.FormatRedacted(index));
            }

            return 0;
        }

        if (comments.Count > 0)
        {
            output.Error.WriteLine(CommentOutput.UnsafeNotice);
        }

        if (settings.Json)
        {
            await output.Out.WriteLineAsync(JsonText.ToJson(comments));
            return 0;
        }

        foreach (var comment in comments)
        {
            await output.Out.WriteLineAsync(CommentOutput.Format(comment));
        }

        return 0;
    }
}

internal sealed class TaskCommentsSettings : CommandSettings
{
    [CommandArgument(0, "<TASK_ID>")]
