    [Fact]
    public async Task EnvBackedClientCreatesCommentWithBearerAuthorization()
    {
        var originalUrl = Environment.GetEnvironmentVariable("JOBTRACK_API_URL");
        var originalKey = Environment.GetEnvironmentVariable("JOBTRACK_API_KEY");
        using var server = new LoopbackHttpServer(HttpStatusCode.Created, """{"id":"comment-env"}""");

        try
        {
            Environment.SetEnvironmentVariable("JOBTRACK_API_URL", server.Url);
            Environment.SetEnvironmentVariable("JOBTRACK_API_KEY", "secret");

            var output = new StringWriter();
            var error = new StringWriter();
            var app = Program.CreateApp(output: output, error: error);

            var exitCode = await app.RunAsync(["task", "comment", "task-42", "Looks good"]);

            Assert.Equal(0, exitCode);
            Assert.Equal($"comment-env{Environment.NewLine}", output.ToString());
            Assert.Equal("", error.ToString());

            var request = await server.Request.WaitAsync(TimeSpan.FromSeconds(5));
            Assert.Equal("POST", request.Method);
            Assert.Equal("/api/tasks/task-42/comments", request.PathAndQuery);
            Assert.Equal("Bearer secret", request.Headers["Authorization"]);

            using var body = JsonDocument.Parse(request.Body);
            Assert.Equal("Looks good", body.RootElement.GetProperty("content").GetString());
        }
        finally
        {
            Environment.SetEnvironmentVariable("JOBTRACK_API_URL", originalUrl);
            Environment.SetEnvironmentVariable("JOBTRACK_API_KEY", originalKey);
        }
    }

