    internal static ICommandApp CreateApp(IJobTrackApi? api = null, TextWriter? output = null, TextWriter? error = null)
    {
        return new JobTrackCommandApp(CreateSpectreApp(api, output, error));
    }

    private static CommandApp CreateSpectreApp(IJobTrackApi? api = null, TextWriter? output = null, TextWriter? error = null)
    {
        var registrar = new TypeRegistrar();
        registrar.RegisterInstance(typeof(IJobTrackOutput), new JobTrackOutput(output ?? Console.Out, error ?? Console.Error));

        if (api is null)
        {
            registrar.RegisterInstance(typeof(IJobTrackApi), new LazyJobTrackApi(() =>
            {
                var (url, key) = ReadEnv();
                return new JobTrackApiClient(url, key);
            }));
        }
        else
        {
            registrar.RegisterInstance(typeof(IJobTrackApi), api);
        }

        var app = new CommandApp(registrar);
        app.Configure(config =>
        {
            config.SetApplicationName("jt");
            config.SetApplicationVersion(Version);
            config.SetExceptionHandler(HandleException);
            config.UseStrictParsing();
            if (output is not null)
            {
                config.ConfigureConsole(AnsiConsole.Create(new AnsiConsoleSettings
                {
                    Out = new AnsiConsoleOutput(output)
                }));
            }

            config.AddBranch("task", task =>
            {
                task.SetDescription("Work with JobTrack tasks.");
                task.AddCommand<TaskListCommand>("list").WithDescription("List tasks.");
                task.AddCommand<TaskShowCommand>("show").WithDescription("Show a task.");
                task.AddCommand<TaskCreateCommand>("create").WithDescription("Create a task.");
                task.AddCommand<TaskUpdateCommand>("update").WithDescription("Update a task.");
                task.AddCommand<TaskCommentsCommand>("comments").WithDescription("List comments for a task.");
                task.AddBranch("comment", comment =>
                {
                    comment.SetDescription(
                        "Create task comments with a quoted content argument or --content; delete comments.");
                    comment.AddExample(new[] { "task", "comment", "task-42", "\"Looks good\"" });
                    comment.AddCommand<TaskCommentCommand>("create").WithDescription("Create a task comment.");
                    comment.AddCommand<TaskCommentDeleteCommand>("delete").WithDescription("Delete a task comment.");
                });
            });

            config.AddCommand<WhoamiCommand>("whoami").WithDescription("Show the authenticated principal.");
            config.AddCommand<VersionCommand>("version").WithDescription("Print the jt version.");
        });

        return app;
    }

    private static int HandleException(Exception exception, ITypeResolver? resolver)
    {
        var output = resolver?.Resolve(typeof(IJobTrackOutput)) as IJobTrackOutput
            ?? new JobTrackOutput(Console.Out, Console.Error);

        output.Error.WriteLine($"jt: {exception.Message}");
        return exception is CommandParseException ? UsageExitCode : 1;
    }

    private static (string Url, string Key) ReadEnv()
    {
        var url = Environment.GetEnvironmentVariable(ApiUrlEnv);
        var key = Environment.GetEnvironmentVariable(ApiKeyEnv);
        if (string.IsNullOrWhiteSpace(url))
        {
            throw new InvalidOperationException($"{ApiUrlEnv} must be set (e.g. http://localhost:5000)");
        }

        if (string.IsNullOrWhiteSpace(key))
        {
            throw new InvalidOperationException($"{ApiKeyEnv} must be set");
        }

        return (url.TrimEnd('/'), key);
    }
}

internal sealed class JobTrackCommandApp(ICommandApp app) : ICommandApp
{
    public void Configure(Action<IConfigurator> configuration)
    {
        app.Configure(configuration);
    }

    public int Run(IEnumerable<string> args, CancellationToken cancellationToken)
    {
        return app.Run(RewriteArgs(args), cancellationToken);
    }

    public Task<int> RunAsync(IEnumerable<string> args, CancellationToken cancellationToken)
    {
        return app.RunAsync(RewriteArgs(args), cancellationToken);
    }

    private static string[] RewriteArgs(IEnumerable<string> args)
    {
        var rewritten = args.ToArray();
        if (ShouldRewriteTaskCommentCreate(rewritten))
        {
            // Preserve the shorthand form `jt task comment <task-id> <content>`.
            return rewritten.Take(2)
                .Append("create")
                .Concat(rewritten.Skip(2))
                .ToArray();
        }

        return rewritten;
    }

    private static bool ShouldRewriteTaskCommentCreate(IReadOnlyList<string> args)
    {
        if (args.Count < 3 ||
            !StringComparer.Ordinal.Equals(args[0], "task") ||
            !StringComparer.Ordinal.Equals(args[1], "comment"))
        {
            return false;
        }

        return !IsHelpOption(args[2]) &&
            !StringComparer.Ordinal.Equals(args[2], "create") &&
            !StringComparer.Ordinal.Equals(args[2], "delete");
    }

    private static bool IsHelpOption(string value)
    {
        return StringComparer.Ordinal.Equals(value, "--help") ||
            StringComparer.Ordinal.Equals(value, "-h") ||
            StringComparer.Ordinal.Equals(value, "-?");
    }
}

