    private sealed class LoopbackTcpProbe : IDisposable
    {
        private readonly TcpListener _listener;

        public LoopbackTcpProbe(string scheme)
        {
            _listener = new TcpListener(IPAddress.Loopback, 0);
            _listener.Start();
            Url = $"{scheme}://127.0.0.1:{((IPEndPoint)_listener.LocalEndpoint).Port}";
            Accepted = AcceptOneAsync();
        }

        public string Url { get; }

        public Task Accepted { get; }

        public void Dispose()
        {
            _listener.Stop();
        }

        private async Task AcceptOneAsync()
        {
            using var client = await _listener.AcceptTcpClientAsync();
        }
    }

    private sealed record LoopbackRequest(
        string Method,
        string PathAndQuery,
        IReadOnlyDictionary<string, string> Headers,
        string Body);

    private sealed class RecordingHandler(Func<HttpRequestMessage, string?, HttpResponseMessage> respond)
        : HttpMessageHandler
    {
        public List<RecordedRequest> Requests { get; } = [];

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            var body = request.Content is null
                ? null
                : await request.Content.ReadAsStringAsync(cancellationToken);

            Requests.Add(new RecordedRequest(
                request.Method.Method,
                request.RequestUri?.PathAndQuery ?? "",
                body,
                request.Content?.Headers.ContentType?.MediaType));

            return respond(request, body);
        }
    }

    private sealed record RecordedRequest(
        string Method,
        string PathAndQuery,
        string? Body,
        string? ContentType);
}

